package msm_test.portal;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.fabricmc.fabric.api.event.player.UseBlockCallback;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.phys.BlockHitResult;

/**
 * Lighting a portal (ADR 0077 D3), written from the ADR's rules: (a) one Fabric {@link UseBlockCallback} for every portal
 * block, on both sides, for a held igniter clicked against a frame; (b) {@link #lightNear} for the {@code light_portal}
 * action. A lit frame is filled with the portal block (axis set, {@link PortalFrame#FILL_FLAGS}) and recorded in the
 * level's portal index (D5). Fire placed by anything else (lightning, spread, a dispenser) lights nothing (limit P6).
 */
public final class PortalLighting {
    /** Every registered portal block, in sorted id order: the first whose frame and igniter match wins (D3). */
    private static final List<PortalBlock> PORTALS = new ArrayList<>();
    private static boolean installed;

    private PortalLighting() {}

    /** Records a registered portal block; called by {@code ModBlocks} once per portal. */
    public static void add(PortalBlock portal) {
        PORTALS.add(portal);
        PORTALS.sort(Comparator.comparing(p -> BuiltInRegistries.BLOCK.getKey(p).toString()));
    }

    /** The registered portal blocks in sorted id order. */
    public static List<PortalBlock> portals() {
        return List.copyOf(PORTALS);
    }

    /** Installs the igniter callback; called once from {@code onInitialize}. */
    public static void register() {
        if (!installed) {
            installed = true;
            UseBlockCallback.EVENT.register(PortalLighting::useIgniter);
        }
    }

    /**
     * D3 (a): the held item is a portal's igniter and the block beside the clicked face is inside an empty, unlit frame of
     * that portal (axis x first, then z). Both sides answer {@code SUCCESS}, so the client never predicts the item's own
     * use (a fire); only the server fills the frame, records it and uses the igniter: a damageable igniter loses one
     * durability, any other is used up one at a time, nothing in creative; the server plays
     * {@code minecraft:item.flintandsteel.use} at the clicked block (orchestrator's decision after B334; the
     * {@code light_portal} action plays nothing).
     */
    private static InteractionResult useIgniter(Player player, Level level, InteractionHand hand, BlockHitResult hit) {
        if (player.isSpectator() || PORTALS.isEmpty()) {
            return InteractionResult.PASS;
        }
        ItemStack stack = player.getItemInHand(hand);
        if (stack.isEmpty()) {
            return InteractionResult.PASS;
        }
        BlockPos inside = hit.getBlockPos().relative(hit.getDirection());
        for (PortalBlock portal : PORTALS) {
            if (!portal.isIgniter(stack)) {
                continue;
            }
            Optional<PortalFrame.Rectangle> frame = unlitFrame(level, inside, portal);
            if (frame.isEmpty()) {
                continue;
            }
            if (level instanceof ServerLevel server) {
                light(server, portal, frame.get());
                // As vanilla's flint and steel: the lighting sound at the clicked frame, for every igniter item.
                BlockPos at = hit.getBlockPos();
                server.playSound(null, at, SoundEvents.FLINTANDSTEEL_USE, SoundSource.BLOCKS, 1.0f,
                        server.getRandom().nextFloat() * 0.4f + 0.8f);
                if (!player.hasInfiniteMaterials()) {
                    if (stack.isDamageableItem()) {
                        stack.hurtAndBreak(1, player, hand.asEquipmentSlot());
                    } else {
                        stack.consume(1, player);
                    }
                }
            }
            return InteractionResult.SUCCESS;
        }
        return InteractionResult.PASS;
    }

    /** The frame of {@code portal} around {@code inside} when it is whole and holds none of the portal yet. */
    public static Optional<PortalFrame.Rectangle> unlitFrame(LevelAccessor level, BlockPos inside, PortalBlock portal) {
        return PortalFrame.find(level, inside, portal::isFrame, portal).filter(r -> PortalFrame.isUnlit(level, r, portal));
    }

    /** Fills {@code frame} with {@code portal} and records it in the level's index. */
    public static void light(ServerLevel level, PortalBlock portal, PortalFrame.Rectangle frame) {
        PortalFrame.fill(level, frame, portal.defaultBlockState());
        PortalIndexAttachment.add(level, portal, frame);
    }

    /**
     * D3 (b), the {@code light_portal} action: lights {@code portal} in an empty frame at {@code at} or, failing that, at
     * the first of its six neighbours (in {@link Direction} order) that is inside one. Returns the lit frame; empty when
     * there is none (nothing happens).
     */
    public static Optional<PortalFrame.Rectangle> lightNear(ServerLevel level, PortalBlock portal, BlockPos at) {
        List<BlockPos> candidates = new ArrayList<>();
        candidates.add(at);
        for (Direction direction : Direction.values()) {
            candidates.add(at.relative(direction));
        }
        for (BlockPos pos : candidates) {
            Optional<PortalFrame.Rectangle> frame = unlitFrame(level, pos, portal);
            if (frame.isPresent()) {
                light(level, portal, frame.get());
                return frame;
            }
        }
        return Optional.empty();
    }

    /** The registered portal block with this id, if it is one. */
    public static Optional<PortalBlock> byId(Identifier id) {
        return BuiltInRegistries.BLOCK.getOptional(id).filter(PortalBlock.class::isInstance).map(PortalBlock.class::cast);
    }
}
